set -e
cd "$(dirname "$0")"
ssh-keygen -q -t rsa -b 3072 -N "" -f host_key
head -c 3000 /dev/urandom > site/report.bin
surl --hostkey host_key --user alice:s3cret --allow-plaintext-auth --list-directories --directory site -v --log-file surl.log ftp://127.0.0.1:8080/ sftp://127.0.0.1:8081/ &
sleep 1
curl -sS -k -u alice:s3cret -T site/report.bin sftp://127.0.0.1:8083/report.bin
curl -sS -u alice:s3cret -o over-ftp.bin ftp://127.0.0.1:8080/report.bin --next -sS -k -u alice:s3cret -o over-sftp.bin sftp://127.0.0.1:8081/report.bin && cmp over-ftp.bin over-sftp.bin && echo identical
kill $(jobs -p)
